    uint256 constant deltax1 = 9807577353449282523749833991162602714540108939249356313450281847061476550356;
    uint256 constant deltax2 = 20312739400673916744373892426359493299942630092308443651739008380078434674519;
    uint256 constant deltay1 = 4030925622659331422964799011367631094964944967764065156804373199745413869611;
    uint256 constant deltay2 = 4950287501793636472916554758468298493978597844113185105753086343599329589192;


    uint256 constant IC0x = 3843208376291320152508330513093868782736874352427917020215041205266924021879;
    uint256 constant IC0y = 16975067305671610377440453361189230602926941034826214656824563308455578495041;

    uint256 constant IC1x = 1313544028348779507487427592753960019821985598375279631801422948064620294339;
    uint256 constant IC1y = 5067770518125442255919797353548984554600986756940043107091397309839773085667;

    uint256 constant IC2x = 11934721703872666090526115086201758080310916001573374871029582410250007869697;
    uint256 constant IC2y = 13038948833004096461214893500319516242245652745012746835315620463795077488471;

    uint256 constant IC3x = 19020980880809178572383912915183607080306970069391548644876130747293591956781;
    uint256 constant IC3y = 19046821408206845669860938531044124227309701025377641804076882162056779102495;

    uint256 constant IC4x = 12077761887797914373397725883311202734112006121862735061948602949226861602903;
    uint256 constant IC4y = 14964509686925682590539713714196504911599077705086626906727760693679471724454;

    uint256 constant IC5x = 19263706472085151095461722601480306142742720995867326403704796127580662944039;
    uint256 constant IC5y = 11941581095347472268454086662353810104496453547212840781017851273329117069225;

    uint256 constant IC6x = 12578740658670416268658658844519289799222417532247790191624474410332851254871;
    uint256 constant IC6y = 11352588336406015486746447646258388830890238026231291117423354707438514775200;

    uint256 constant IC7x = 2690603546978981189545790635922752273511520592305716931803027167953338241257;
    uint256 constant IC7y = 4705356686558929125470549152141658940531347997442695600736994680321918273257;

    uint256 constant IC8x = 4000362046506224782508588092973741169245411904820386573277215535974802062112;
    uint256 constant IC8y = 20354135950804404939930059589944185221348063808194906198276910054557827409246;

    uint256 constant IC9x = 7929517409357441524357681853127310747173861512293233128648056888483850003487;
    uint256 constant IC9y = 16188668352259294396739586880340613498302521779770906227569760240371148626460;

    uint256 constant IC10x = 7857719990539687820395816393807593298573308812115157396408148574951313943635;
    uint256 constant IC10y = 1428061513022012163459278080675744091851511248592828893346212462382872291900;


    // Memory data
    uint16 constant pVk = 0;
    uint16 constant pPairing = 128;

    uint16 constant pLastMem = 896;

    function verifyProof(uint[2] calldata _pA, uint[2][2] calldata _pB, uint[2] calldata _pC, uint[10] calldata _pubSignals) public view returns (bool) {
        assembly {
            function checkField(v) {
                if iszero(lt(v, r)) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

            // G1 function to multiply a G1 value(x,y) to value in an address
            function g1_mulAccC(pR, x, y, s) {
                let success
                let mIn := mload(0x40)
                mstore(mIn, x)
                mstore(add(mIn, 32), y)
                mstore(add(mIn, 64), s)

                success := staticcall(sub(gas(), 2000), 7, mIn, 96, mIn, 64)

                if iszero(success) {
                    mstore(0, 0)
                    return(0, 0x20)
                }

                mstore(add(mIn, 64), mload(pR))
                mstore(add(mIn, 96), mload(add(pR, 32)))

                success := staticcall(sub(gas(), 2000), 6, mIn, 128, pR, 64)

                if iszero(success) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

            function checkPairing(pA, pB, pC, pubSignals, pMem) -> isOk {
                let _pPairing := add(pMem, pPairing)
                let _pVk := add(pMem, pVk)

                mstore(_pVk, IC0x)
                mstore(add(_pVk, 32), IC0y)

                // Compute the linear combination vk_x

                g1_mulAccC(_pVk, IC1x, IC1y, calldataload(add(pubSignals, 0)))

                g1_mulAccC(_pVk, IC2x, IC2y, calldataload(add(pubSignals, 32)))

                g1_mulAccC(_pVk, IC3x, IC3y, calldataload(add(pubSignals, 64)))

                g1_mulAccC(_pVk, IC4x, IC4y, calldataload(add(pubSignals, 96)))

                g1_mulAccC(_pVk, IC5x, IC5y, calldataload(add(pubSignals, 128)))

                g1_mulAccC(_pVk, IC6x, IC6y, calldataload(add(pubSignals, 160)))

                g1_mulAccC(_pVk, IC7x, IC7y, calldataload(add(pubSignals, 192)))

                g1_mulAccC(_pVk, IC8x, IC8y, calldataload(add(pubSignals, 224)))

                g1_mulAccC(_pVk, IC9x, IC9y, calldataload(add(pubSignals, 256)))

                g1_mulAccC(_pVk, IC10x, IC10y, calldataload(add(pubSignals, 288)))


                // -A
                mstore(_pPairing, calldataload(pA))
                mstore(add(_pPairing, 32), mod(sub(q, calldataload(add(pA, 32))), q))

                // B
                mstore(add(_pPairing, 64), calldataload(pB))
                mstore(add(_pPairing, 96), calldataload(add(pB, 32)))
                mstore(add(_pPairing, 128), calldataload(add(pB, 64)))
                mstore(add(_pPairing, 160), calldataload(add(pB, 96)))

                // alpha1
                mstore(add(_pPairing, 192), alphax)
                mstore(add(_pPairing, 224), alphay)

                // beta2
                mstore(add(_pPairing, 256), betax1)
                mstore(add(_pPairing, 288), betax2)
                mstore(add(_pPairing, 320), betay1)
                mstore(add(_pPairing, 352), betay2)

                // vk_x
                mstore(add(_pPairing, 384), mload(add(pMem, pVk)))
                mstore(add(_pPairing, 416), mload(add(pMem, add(pVk, 32))))


                // gamma2
                mstore(add(_pPairing, 448), gammax1)
                mstore(add(_pPairing, 480), gammax2)
                mstore(add(_pPairing, 512), gammay1)
                mstore(add(_pPairing, 544), gammay2)

                // C
                mstore(add(_pPairing, 576), calldataload(pC))
                mstore(add(_pPairing, 608), calldataload(add(pC, 32)))

                // delta2
                mstore(add(_pPairing, 640), deltax1)
                mstore(add(_pPairing, 672), deltax2)
                mstore(add(_pPairing, 704), deltay1)
                mstore(add(_pPairing, 736), deltay2)


